+import type { CloudAgent } from '@/hooks/useAgents';
+
+interface DeployedAgentsListProps {
+  agents: CloudAgent[];
+  isLoading?: boolean;
+  onConnect: (agent: CloudAgent) => void;
+  onStart: (id: string) => Promise<boolean>;
+  onStop: (id: string) => Promise<boolean>;
+  onDelete: (id: string) => Promise<boolean>;
+}
+
+const statusConfig: Record<
+  CloudAgent['status'],
+  { color: string; bgColor: string; label: string; canConnect: boolean }
+> = {
+  pending: {
+    color: 'text-yellow-400',
+    bgColor: 'bg-yellow-500/20',
+    label: 'Pending',
+    canConnect: false,
+  },
+  creating_app: {
+    color: 'text-yellow-400',
+    bgColor: 'bg-yellow-500/20',
+    label: 'Creating...',
+    canConnect: false,
+  },
+  creating_volume: {
+    color: 'text-yellow-400',
+    bgColor: 'bg-yellow-500/20',
+    label: 'Creating...',
+    canConnect: false,
+  },
+  creating_machine: {
+    color: 'text-yellow-400',
+    bgColor: 'bg-yellow-500/20',
+    label: 'Creating...',
+    canConnect: false,
+  },
+  running: {
+    color: 'text-green-400',
+    bgColor: 'bg-green-500/20',
+    label: 'Running',
+    canConnect: true,
+  },
+  stopped: {
+    color: 'text-gray-400',
+    bgColor: 'bg-gray-500/20',
+    label: 'Stopped',
+    canConnect: false,
+  },
+  starting: {
+    color: 'text-blue-400',
+    bgColor: 'bg-blue-500/20',
+    label: 'Starting...',
+    canConnect: false,
+  },
+  stopping: {
+    color: 'text-orange-400',
+    bgColor: 'bg-orange-500/20',
+    label: 'Stopping...',
+    canConnect: false,
+  },
+  error: { color: 'text-red-400', bgColor: 'bg-red-500/20', label: 'Error', canConnect: false },
+};
+
+export function DeployedAgentsList({
+  agents,
+  isLoading,
+  onConnect,
+  onStart,
+  onStop,
+  onDelete,
+}: DeployedAgentsListProps) {
+  const [loadingActions, setLoadingActions] = useState<Record<string, string>>({});
+  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);
+
+  if (isLoading) {
+    return (
+      <div className="mt-6 flex items-center justify-center py-8">
+        <Loader2 className="h-6 w-6 animate-spin text-white/40" />
+      </div>
+    );
+  }
+
+  if (agents.length === 0) {
